// ============================================================================
// StringView — Zero-Copy String Reference
// ============================================================================

struct StringView {
    const char* ptr;
    size_t len;

    JSON_PARSER_INLINE StringView() : ptr(nullptr), len(0) {}
    JSON_PARSER_INLINE StringView(const char* p, size_t l) : ptr(p), len(l) {}
    JSON_PARSER_INLINE StringView(std::string_view sv) : ptr(sv.data()), len(sv.size()) {}

    JSON_PARSER_INLINE char operator[](size_t i) const { return ptr[i]; }
    JSON_PARSER_INLINE bool empty() const { return len == 0; }
    JSON_PARSER_INLINE char front() const { return ptr[0]; }
    JSON_PARSER_INLINE char back() const { return ptr[len - 1]; }

    JSON_PARSER_INLINE bool operator==(const StringView& o) const {
        if (len != o.len) return false;
        return std::memcmp(ptr, o.ptr, len) == 0;
    }
    JSON_PARSER_INLINE bool operator!=(const StringView& o) const { return !(*this == o); }
    JSON_PARSER_INLINE bool operator<(const StringView& o) const {
        int cmp = std::memcmp(ptr, o.ptr, std::min(len, o.len));
        if (cmp != 0) return cmp < 0;
        return len < o.len;
    }

    JSON_PARSER_INLINE bool starts_with(StringView prefix) const {
        if (prefix.len > len) return false;
        return std::memcmp(ptr, prefix.ptr, prefix.len) == 0;
    }
    JSON_PARSER_INLINE bool ends_with(StringView suffix) const {
        if (suffix.len > len) return false;
        return std::memcmp(ptr + len - suffix.len, suffix.ptr, suffix.len) == 0;
    }
    JSON_PARSER_INLINE bool contains(char c) const {
        for (size_t i = 0; i < len; ++i) if (ptr[i] == c) return true;
        return false;
    }

    JSON_PARSER_INLINE std::string to_string() const {
        return std::string(ptr, len);
    }

    friend std::ostream& operator<<(std::ostream& os, const StringView& sv) {
        os.write(sv.ptr, static_cast<std::streamsize>(sv.len));
        return os;
    }
};

namespace std {
    template<> struct hash<StringView> {
        size_t operator()(const StringView& sv) const {
            size_t h = 0;
            for (size_t i = 0; i < sv.len; ++i) {
                h = h * 31 + static_cast<unsigned char>(sv.ptr[i]);
            }
            return h;
        }
    };
}

// ============================================================================
// ArenaAllocator — Bump-Pointer Memory Pool
// ============================================================================

struct ArenaStats {
    size_t bytes_allocated;
    size_t block_count;
    size_t peak_usage;
};

class ArenaAllocator {
public:
    static constexpr size_t INITIAL_BLOCK_SIZE = 4096;
    static constexpr size_t MAX_BLOCK_SIZE = 1048576; // 1 MB
    static constexpr size_t ALIGNMENT = 16;

private:
    struct Block {
        char* data;
        size_t capacity;
    };

    std::vector<Block*> m_blocks;
    Block* m_current_block;
    char* m_cursor;
    size_t m_block_size;
    size_t m_peak_usage;
    size_t m_total_allocated;

    void grow(size_t needed);

public:
    ArenaAllocator();
    ~ArenaAllocator();

    // Non-copyable, movable
    ArenaAllocator(const ArenaAllocator&) = delete;
    ArenaAllocator& operator=(const ArenaAllocator&) = delete;
    ArenaAllocator(ArenaAllocator&& other) noexcept;
    ArenaAllocator& operator=(ArenaAllocator&& other) noexcept;

    void* allocate(size_t size, size_t alignment = ALIGNMENT);
    template<typename T, typename... Args>
    T* make(Args&&... args) {
        void* ptr = allocate(sizeof(T), alignof(T));
        return new (ptr) T(std::forward<Args>(args)...);
    }
    void reset();
    void destroy_all();
    ArenaStats stats() const;
    size_t remaining() const;
};

