class JsonArray;
class JsonObject;

class JsonValue {
public:
    enum class Type : uint8_t {
        Null, Bool, Int, Float, String, Array, Object
    };

private:
    Type m_type;
    union {
        bool         m_bool;
        int64_t      m_int;
        double       m_float;
        StringView   m_string;
