    JSON_PARSER_INLINE explicit JsonValue(std::nullptr_t) : m_type(Type::Null), m_bool(false) {}
    JSON_PARSER_INLINE explicit JsonValue(bool v) : m_type(Type::Bool), m_bool(v) {}
    JSON_PARSER_INLINE explicit JsonValue(int v) : m_type(Type::Int), m_int(v) {}
    JSON_PARSER_INLINE explicit JsonValue(int64_t v) : m_type(Type::Int), m_int(v) {}
    JSON_PARSER_INLINE explicit JsonValue(double v) : m_type(Type::Float), m_float(v) {}
    JSON_PARSER_INLINE JsonValue(StringView s) : m_type(Type::String), m_string(s) {}
    JSON_PARSER_INLINE JsonValue(JsonArray* arr) : m_type(Type::Array), m_array(arr) {}
    JSON_PARSER_INLINE JsonValue(JsonObject* obj) : m_type(Type::Object), m_object(obj) {}

    JsonValue(const JsonValue& other);
    JsonValue(JsonValue&& other) noexcept;
    JsonValue& operator=(const JsonValue& other);
    JsonValue& operator=(JsonValue&& other) noexcept;
    ~JsonValue();

    JSON_PARSER_INLINE Type type() const { return m_type; }
    JSON_PARSER_INLINE bool is_null() const { return m_type == Type::Null; }
    JSON_PARSER_INLINE bool is_bool() const { return m_type == Type::Bool; }
    JSON_PARSER_INLINE bool is_int() const { return m_type == Type::Int; }
    JSON_PARSER_INLINE bool is_float() const { return m_type == Type::Float; }
    JSON_PARSER_INLINE bool is_number() const { return is_int() || is_float(); }
    JSON_PARSER_INLINE bool is_string() const { return m_type == Type::String; }
    JSON_PARSER_INLINE bool is_array() const { return m_type == Type::Array; }
    JSON_PARSER_INLINE bool is_object() const { return m_type == Type::Object; }

    JSON_PARSER_INLINE bool get_bool() const { assert(is_bool()); return m_bool; }
    JSON_PARSER_INLINE int64_t get_int() const { assert(is_int()); return m_int; }
    JSON_PARSER_INLINE double get_float() const { assert(is_float()); return m_float; }
    JSON_PARSER_INLINE StringView get_string() const { assert(is_string()); return m_string; }
    JSON_PARSER_INLINE JsonArray* get_array() const { assert(is_array()); return m_array; }
    JSON_PARSER_INLINE JsonObject* get_object() const { assert(is_object()); return m_object; }

