// ============================================================================
// ArenaAllocator Implementation
// ============================================================================

ArenaAllocator::ArenaAllocator()
    : m_current_block(nullptr), m_cursor(nullptr),
      m_block_size(INITIAL_BLOCK_SIZE), m_peak_usage(0), m_total_allocated(0) {
    grow(INITIAL_BLOCK_SIZE);
}

ArenaAllocator::~ArenaAllocator() {
    destroy_all();
}

ArenaAllocator::ArenaAllocator(ArenaAllocator&& other) noexcept
    : m_blocks(std::move(other.m_blocks)),
      m_current_block(other.m_current_block),
      m_cursor(other.m_cursor),
      m_block_size(other.m_block_size),
      m_peak_usage(other.m_peak_usage),
      m_total_allocated(other.m_total_allocated) {
    other.m_current_block = nullptr;
    other.m_cursor = nullptr;
    other.m_block_size = INITIAL_BLOCK_SIZE;
    other.m_peak_usage = 0;
    other.m_total_allocated = 0;
}

ArenaAllocator& ArenaAllocator::operator=(ArenaAllocator&& other) noexcept {
    if (this != &other) {
        destroy_all();
        m_blocks = std::move(other.m_blocks);
        m_current_block = other.m_current_block;
        m_cursor = other.m_cursor;
        m_block_size = other.m_block_size;
        m_peak_usage = other.m_peak_usage;
        m_total_allocated = other.m_total_allocated;
        other.m_current_block = nullptr;
        other.m_cursor = nullptr;
        other.m_block_size = INITIAL_BLOCK_SIZE;
        other.m_peak_usage = 0;
        other.m_total_allocated = 0;
    }
    return *this;
}

void ArenaAllocator::grow(size_t needed) {
    size_t block_size = std::max(m_block_size, needed);
    block_size = std::min(block_size, MAX_BLOCK_SIZE);

    Block* block = new Block;
    block->capacity = block_size;
    block->data = static_cast<char*>(std::aligned_alloc(ALIGNMENT, block_size));
    if (!block->data) {
        throw std::bad_alloc();
    }

    m_blocks.push_back(block);
    m_current_block = block;
    m_cursor = block->data;
    m_block_size = block_size * 2;
}

void* ArenaAllocator::allocate(size_t size, size_t alignment) {
    // Align cursor
    uintptr_t addr = reinterpret_cast<uintptr_t>(m_cursor);
    uintptr_t aligned = (addr + alignment - 1) & ~(alignment - 1);
    size_t padding = aligned - addr;

    if (padding + size > m_current_block->capacity - (m_cursor - m_current_block->data)) {
        grow(padding + size);
        addr = reinterpret_cast<uintptr_t>(m_cursor);
        aligned = (addr + alignment - 1) & ~(alignment - 1);
        padding = aligned - addr;
    }

    m_cursor = reinterpret_cast<char*>(aligned) + size;
    size_t used = m_cursor - m_current_block->data;
    if (used > m_peak_usage) m_peak_usage = used;
    m_total_allocated += size + padding;

    return reinterpret_cast<void*>(aligned);
}

void ArenaAllocator::reset() {
    for (auto* block : m_blocks) {
        delete[] block->data;
    }
    m_blocks.clear();
    m_peak_usage = 0;
    m_total_allocated = 0;
    m_block_size = INITIAL_BLOCK_SIZE;
    grow(INITIAL_BLOCK_SIZE);
}

void ArenaAllocator::destroy_all() {
    for (auto* block : m_blocks) {
        delete[] block->data;
    }
    m_blocks.clear();
    m_current_block = nullptr;
    m_cursor = nullptr;
    m_block_size = INITIAL_BLOCK_SIZE;
    m_peak_usage = 0;
    m_total_allocated = 0;
}

ArenaStats ArenaAllocator::stats() const {
    size_t total_bytes = 0;
    for (const auto* block : m_blocks) {
        total_bytes += block->capacity;
    }
    return {total_bytes, m_blocks.size(), m_peak_usage};
}

size_t ArenaAllocator::remaining() const {
    if (!m_current_block) return 0;
    return m_current_block->capacity - (m_cursor - m_current_block->data);
}

// ============================================================================
// TokenStreamBuffer Implementation
// ============================================================================

TokenStreamBuffer::TokenStreamBuffer(size_t initial_capacity)
    : tokens(nullptr), count(0), capacity(0), current(0) {
    if (initial_capacity > 0) {
        reserve(initial_capacity);
    }
}

void TokenStreamBuffer::reserve(size_t new_capacity) {
    if (new_capacity <= capacity) return;

    size_t actual = std::max(new_capacity, capacity * 3 / 2 + 8);
    Token* new_tokens = static_cast<Token*>(std::realloc(tokens, actual * sizeof(Token)));
    if (!new_tokens && capacity == 0) {
        throw std::bad_alloc();
    }
    tokens = new_tokens;
    capacity = actual;
}

void TokenStreamBuffer::push(Token token) {
    if (count >= capacity) {
        reserve(count + 1);
    }
    tokens[count++] = token;
}

JSON_PARSER_INLINE Token TokenStreamBuffer::next() {
    if (current < count) {
        return tokens[current++];
    }
    return Token{TokenType::EndOfInput, StringView(), 0, 0};
}

JSON_PARSER_INLINE bool TokenStreamBuffer::has_more() const {
    return current < count;
}

JSON_PARSER_INLINE void TokenStreamBuffer::reset() {
    current = 0;
}

// ============================================================================
// Lexer Implementation
// ============================================================================

Lexer::Lexer(const char* input, size_t length)
    : m_input(input), m_length(length), m_pos(0), m_line(1), m_column(1) {}

JSON_PARSER_INLINE char Lexer::peek() const {
    if (m_pos < m_length) {
        return m_input[m_pos];
    }
    return '\0';
}

JSON_PARSER_INLINE char Lexer::next_char() {
    if (m_pos < m_length) {
        char c = m_input[m_pos++];
        if (c == '\n') {
            ++m_line;
            m_column = 1;
        } else {
            ++m_column;
        }
        return c;
    }
    return '\0';
}

JSON_PARSER_INLINE void Lexer::skip_whitespace() {
    while (m_pos < m_length) {
        char c = m_input[m_pos];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
            ++m_pos;
            if (c == '\n') {
                ++m_line;
                m_column = 1;
            } else {
                ++m_column;
            }
        } else {
            break;
        }
    }
}

bool Lexer::expect(char expected) {
    skip_whitespace();
    if (m_pos >= m_length) return false;
    if (m_input[m_pos] != expected) return false;
    next_char();
    return true;
}

Token Lexer::parse_number_literal() {
    size_t start = m_pos;
    size_t line = m_line;
    size_t column = m_column;
    bool is_float = false;

    if (m_pos < m_length && m_input[m_pos] == '-') {
        ++m_pos;
        ++m_column;
    }

    if (m_pos < m_length && m_input[m_pos] == '0') {
        ++m_pos;
        ++m_column;
        if (m_pos < m_length && (m_input[m_pos] >= '1' && m_input[m_pos] <= '9')) {
            while (m_pos < m_length && ((m_input[m_pos] >= '0' && m_input[m_pos] <= '9') || 
                   m_input[m_pos] == '.' || m_input[m_pos] == 'e' || m_input[m_pos] == 'E' ||
                   m_input[m_pos] == '+' || m_input[m_pos] == '-')) {
                if (m_input[m_pos] == '.' || m_input[m_pos] == 'e' || m_input[m_pos] == 'E') {
                    is_float = true;
                }
                ++m_pos;
                ++m_column;
            }
            return Token{TokenType::Invalid, StringView(m_input + start, m_pos - start), line, column};
        }
    } else {
        if (m_pos < m_length && m_input[m_pos] >= '1' && m_input[m_pos] <= '9') {
            ++m_pos;
            ++m_column;
        } else {
            return Token{TokenType::Invalid, StringView(m_input + start, 0), line, column};
        }
        while (m_pos < m_length && m_input[m_pos] >= '0' && m_input[m_pos] <= '9') {
            ++m_pos;
            ++m_column;
        }
    }

    if (m_pos < m_length && m_input[m_pos] == '.') {
        is_float = true;
        ++m_pos;
        ++m_column;
        if (m_pos >= m_length || m_input[m_pos] < '0' || m_input[m_pos] > '9') {
            return Token{TokenType::Invalid, StringView(m_input + start, m_pos - start), line, column};
        }
        while (m_pos < m_length && m_input[m_pos] >= '0' && m_input[m_pos] <= '9') {
            ++m_pos;
            ++m_column;
        }
    }

    if (m_pos < m_length && (m_input[m_pos] == 'e' || m_input[m_pos] == 'E')) {
        is_float = true;
        ++m_pos;
        ++m_column;
        if (m_pos < m_length && (m_input[m_pos] == '+' || m_input[m_pos] == '-')) {
            ++m_pos;
            ++m_column;
        }
        if (m_pos >= m_length || m_input[m_pos] < '0' || m_input[m_pos] > '9') {
            return Token{TokenType::Invalid, StringView(m_input + start, m_pos - start), line, column};
        }
        while (m_pos < m_length && m_input[m_pos] >= '0' && m_input[m_pos] <= '9') {
            ++m_pos;
            ++m_column;
        }
    }

    Token tok;
    tok.type = TokenType::Number;
    tok.text = StringView(m_input + start, m_pos - start);
    tok.line = line;
    tok.column = column;
    return tok;
}

Token Lexer::parse_string_literal() {
    size_t start = m_pos;
    size_t line = m_line;
    size_t column = m_column;

    if (m_pos >= m_length || m_input[m_pos] != '"') {
        return Token{TokenType::Invalid, StringView(), line, column};
    }
    ++m_pos;
    ++m_column;

    while (m_pos < m_length) {
        char c = m_input[m_pos];
        if (c == '\\') {
            m_pos += 2;
            if (m_pos > m_length) break;
            m_column += 2;
        } else if (c == '"') {
            ++m_pos;
            ++m_column;
            return Token{TokenType::String, StringView(m_input + start, m_pos - start), line, column};
        } else if (c == '\n') {
            ++m_line;
            m_column = 1;
            ++m_pos;
        } else {
            ++m_pos;
            ++m_column;
        }
    }

    return Token{TokenType::Invalid, StringView(m_input + start, m_pos - start), line, column};
}

static bool starts_with(const char* str, const char* prefix) {
    return std::strncmp(str, prefix, std::strlen(prefix)) == 0;
}

TokenStreamBuffer Lexer::tokenize() {
    constexpr size_t INITIAL_TOKENS = 256;
    TokenStreamBuffer buffer(INITIAL_TOKENS);

    while (m_pos < m_length) {
        skip_whitespace();
        if (m_pos >= m_length) break;

        size_t line = m_line;
        size_t column = m_column;
        char c = peek();

        switch (c) {
            case '{':
                buffer.push({TokenType::LBrace, StringView(), line, column});
                next_char();
                break;
            case '}':
                buffer.push({TokenType::RBrace, StringView(), line, column});
                next_char();
                break;
            case '[':
                buffer.push({TokenType::LBracket, StringView(), line, column});
                next_char();
                break;
            case ']':
                buffer.push({TokenType::RBracket, StringView(), line, column});
                next_char();
                break;
            case ':':
                buffer.push({TokenType::Colon, StringView(), line, column});
                next_char();
                break;
            case ',':
                buffer.push({TokenType::Comma, StringView(), line, column});
                next_char();
                break;
            case '"':
                buffer.push(parse_string_literal());
                break;
            case '-':
            case '0': case '1': case '2': case '3': case '4':
            case '5': case '6': case '7': case '8': case '9':
                buffer.push(parse_number_literal());
                break;
            default:
                if (m_pos + 4 <= m_length && starts_with(m_input + m_pos, "null")) {
                    m_pos += 4;
                    m_column += 4;
                    buffer.push({TokenType::Null, StringView(m_input + m_pos - 4, 4), line, column});
                } else if (m_pos + 4 <= m_length && starts_with(m_input + m_pos, "true")) {
                    m_pos += 4;
                    m_column += 4;
                    buffer.push({TokenType::True, StringView(m_input + m_pos - 4, 4), line, column});
                } else if (m_pos + 5 <= m_length && starts_with(m_input + m_pos, "false")) {
                    m_pos += 5;
                    m_column += 5;
                    buffer.push({TokenType::False, StringView(m_input + m_pos - 5, 5), line, column});
                } else {
                    buffer.push({TokenType::Invalid, StringView(&c, 1), line, column});
                    next_char();
                }
                break;
        }
    }

    buffer.push({TokenType::EndOfInput, StringView(), m_line, m_column});
    return buffer;
}
```

### Key Design Points:
- Hand-written state machine tokenizer (no regex, no library calls)
- Direct character comparison for maximum throughput
- Escape sequences handled inline during string parsing
- Number parsing handles: integers, floats, scientific notation, negative numbers
- TokenStreamBuffer uses realloc-based growth (1.5x factor)
- All tokens stored in contiguous array for cache-friendly iteration
- Line/column tracking for error reporting
- EndOfInput sentinel token marks stream termination

