void JsonValue::copy_from(const JsonValue& other) {
    m_type = other.m_type;
    switch (m_type) {
        case Type::Null:
        case Type::Bool:
            m_bool = other.m_bool;
            break;
        case Type::Int:
            m_int = other.m_int;
            break;
        case Type::Float:
            m_float = other.m_float;
            break;
        case Type::String:
            m_string = other.m_string;
            break;
        case Type::Array:
            m_array = new JsonArray(other.capacity);
            for (size_t i = 0; i < other.size; ++i) {
                m_array->push_back(other.elements[i]);
            }
            break;
        case Type::Object:
            m_object = new JsonObject(other.capacity);
            for (size_t i = 0; i < other.size; ++i) {
                m_object->entries[i].key = other.entries[i].key;
                m_object->entries[i].value = other.entries[i].value;
            }
            m_object->size = other.size;
            break;
    }
}

void JsonValue::move_from(JsonValue&& other) noexcept {
    destroy();
    m_type = other.m_type;
    std::memcpy(this, &other, sizeof(JsonValue));
    other.m_type = Type::Null;
}

void JsonValue::destroy() {
    if (m_type == Type::Array && m_array) {
        delete m_array;
        m_array = nullptr;
    } else if (m_type == Type::Object && m_object) {
        delete m_object;
        m_object = nullptr;
    }
    m_type = Type::Null;
}

JsonValue::JsonValue(const JsonValue& other) : m_type(Type::Null), m_bool(false) {
    copy_from(other);
}

JsonValue::JsonValue(JsonValue&& other) noexcept : m_type(Type::Null), m_bool(false) {
    move_from(std::move(other));
}

JsonValue& JsonValue::operator=(const JsonValue& other) {
    if (this != &other) {
        destroy();
        copy_from(other);
    }
    return *this;
}

JsonValue& JsonValue::operator=(JsonValue&& other) noexcept {
    if (this != &other) {
        move_from(std::move(other));
    }
    return *this;
}

JsonValue::~JsonValue() {
    destroy();
}

std::ostream& operator<<(std::ostream& os, const JsonValue& v) {
    JsonSerializer ser;
    os << ser.serialize(v);
    return os;
}

