// JsonArray Implementation
// ============================================================================

JsonArray::JsonArray(size_t initial_capacity)
    : elements(nullptr), size(0), capacity(0) {
    if (initial_capacity > 0) {
        reserve(initial_capacity);
    }
}

void JsonArray::reserve(size_t new_capacity) {
    if (new_capacity <= capacity) return;
    size_t actual = std::max(new_capacity, capacity * 2 + 4);
    JsonValue* new_elements = static_cast<JsonValue*>(std::realloc(elements, actual * sizeof(JsonValue)));
    if (!new_elements && capacity == 0) {
        throw std::bad_alloc();
    }
    elements = new_elements;
    capacity = actual;
}

void JsonArray::push_back(const JsonValue& value) {
    if (size >= capacity) {
        reserve(size + 1);
    }
    new (&elements[size]) JsonValue(value);
    ++size;
}

void JsonArray::push_back(JsonValue&& value) {
    if (size >= capacity) {
        reserve(size + 1);
    }
    new (&elements[size]) JsonValue(std::move(value));
    ++size;
}

// ============================================================================
// JsonObject Implementation
// ============================================================================

JsonObject::JsonObject(size_t initial_capacity)
    : entries(nullptr), size(0), capacity(0) {
    if (initial_capacity > 0) {
        reserve(initial_capacity);
    }
}

void JsonObject::reserve(size_t new_capacity) {
    if (new_capacity <= capacity) return;
    size_t actual = std::max(new_capacity, capacity * 2 + 4);
    Entry* new_entries = static_cast<Entry*>(std::realloc(entries, actual * sizeof(Entry)));
    if (!new_entries && capacity == 0) {
        throw std::bad_alloc();
    }
    entries = new_entries;
    capacity = actual;
}

JsonObject::Entry* JsonObject::find(const StringView& key) const {
    for (size_t i = 0; i < size; ++i) {
        if (entries[i].key == key) {
            return &entries[i];
        }
    }
    return nullptr;
}

bool JsonObject::contains(const StringView& key) const {
    return find(key) != nullptr;
}

JsonValue& JsonObject::operator[](const StringView& key) {
    Entry* existing = find(key);
    if (existing) {
        return existing->value;
    }
    if (size >= capacity) {
        reserve(size + 1);
    }
    entries[size].key = key;
    ++size;
    return entries[size - 1].value;
}

// ============================================================================
// JsonParser Implementation
// ============================================================================

JsonParser::JsonParser(ArenaAllocator& arena, TokenStreamBuffer& tokens)
    : m_arena(arena), m_tokens(tokens), m_error("") {}

void JsonParser::error(const char* msg) {
    m_error = msg;
}

Token JsonParser::expect_token(TokenType type) {
    Token tok = m_tokens.next();
    if (!tok.is(type)) {
        error("Expected token");
    }
    return tok;
}

JsonValue JsonParser::parse() {
    JsonValue result = parse_value();
    Token end = m_tokens.next();
    if (!end.is(TokenType::EndOfInput)) {
        error("Unexpected content after JSON value");
    }
    return result;
}

JsonValue JsonParser::parse_value() {
    Token tok = m_tokens.next();

    switch (tok.type) {
        case TokenType::Null:
            return JsonValue(nullptr);
        case TokenType::True:
            return JsonValue(true);
        case TokenType::False:
            return JsonValue(false);
        case TokenType::Number: {
            std::string num_str(tok.text.ptr, tok.text.len);
            char* end = nullptr;
            double val = std::strtod(num_str.c_str(), &end);
            if (num_str.find('.') != std::string::npos || 
                num_str.find('e') != std::string::npos || 
                num_str.find('E') != std::string::npos) {
                return JsonValue(val);
            } else {
                int64_t ival = static_cast<int64_t>(val);
                return JsonValue(ival);
            }
        }
        case TokenType::String:
            return JsonValue(tok.text);
        case TokenType::LBracket:
            return parse_array();
        case TokenType::LBrace:
            return parse_object();
        case TokenType::Invalid:
            error("Invalid token");
            return JsonValue(nullptr);
        default:
            error("Unexpected token");
            return JsonValue(nullptr);
    }
}

JsonValue JsonParser::parse_null() {
    Token tok = expect_token(TokenType::Null);
    if (!tok.is(TokenType::Null)) {
        return JsonValue(nullptr);
    }
    return JsonValue(nullptr);
}

JsonValue JsonParser::parse_bool() {
    Token tok = m_tokens.next();
    if (tok.is(TokenType::True)) return JsonValue(true);
    if (tok.is(TokenType::False)) return JsonValue(false);
    error("Expected boolean");
    return JsonValue(nullptr);
}

JsonValue JsonParser::parse_number() {
    Token tok = expect_token(TokenType::Number);
    if (!tok.is(TokenType::Number)) {
        return JsonValue(nullptr);
    }
    std::string num_str(tok.text.ptr, tok.text.len);
    char* end = nullptr;
    double val = std::strtod(num_str.c_str(), &end);
    if (num_str.find('.') != std::string::npos || 
        num_str.find('e') != std::string::npos || 
        num_str.find('E') != std::string::npos) {
        return JsonValue(val);
    } else {
        int64_t ival = static_cast<int64_t>(val);
        return JsonValue(ival);
    }
}

JsonValue JsonParser::parse_string() {
    Token tok = expect_token(TokenType::String);
    if (!tok.is(TokenType::String)) {
        return JsonValue(nullptr);
    }
    return JsonValue(tok.text);
}

JsonValue JsonParser::parse_array() {
    auto* arr = m_arena.make<JsonArray>(8);

    while (true) {
        Token tok = m_tokens.peek();
        if (tok.is(TokenType::RBracket)) {
            m_tokens.next();
            break;
        }
        if (tok.is(TokenType::EndOfInput)) {
            error("Unterminated array");
            break;
        }
        arr->push_back(parse_value());

        tok = m_tokens.peek();
        if (tok.is(TokenType::Comma)) {
            m_tokens.next();
        } else if (!tok.is(TokenType::RBracket) && !tok.is(TokenType::EndOfInput)) {
            error("Expected comma or closing bracket");
        }
    }

    return JsonValue(arr);
}

JsonValue JsonParser::parse_object() {
    auto* obj = m_arena.make<JsonObject>(4);

    while (true) {
        Token tok = m_tokens.peek();
        if (tok.is(TokenType::RBrace)) {
            m_tokens.next();
            break;
        }
        if (tok.is(TokenType::EndOfInput)) {
            error("Unterminated object");
            break;
        }

        Token key_tok = m_tokens.next();
        if (!key_tok.is(TokenType::String)) {
            error("Expected string key in object");
            return JsonValue(nullptr);
        }

        Token colon_tok = m_tokens.next();
        if (!colon_tok.is(TokenType::Colon)) {
            error("Expected colon after key");
            return JsonValue(nullptr);
        }

        JsonValue value = parse_value();
        obj->operator[](key_tok.text) = std::move(value);

        tok = m_tokens.peek();
        if (tok.is(TokenType::Comma)) {
            m_tokens.next();
        } else if (!tok.is(TokenType::RBrace) && !tok.is(TokenType::EndOfInput)) {
            error("Expected comma or closing brace");
        }
    }

    return JsonValue(obj);
}

// ============================================================================
// Utility Functions
// ============================================================================

JSON_PARSER_INLINE JsonValue parse(const char* input, size_t length) {
    ArenaAllocator arena;
    Lexer lexer(input, length);
    auto tokens = lexer.tokenize();
    JsonParser parser(arena, tokens);
    return parser.parse();
}

JSON_PARSER_INLINE JsonValue parse(std::string_view sv) {
    return parse(sv.data(), sv.size());
}

JSON_PARSER_INLINE std::string format(const JsonValue& value, int indent) {
    JsonSerializer serializer;
    return serializer.format(value, indent);
}
```

### Key Design Points:
- Recursive descent parsing with direct token consumption
- Error handling via m_error string (null JsonValue returned on error)
- Deep copy semantics in JsonValue constructor/assignment
- Arena-based allocation for arrays and objects
- Number parsing distinguishes int vs float based on presence of '.', 'e', 'E'
- Object keys stored as StringView (zero-copy from source)
- Trailing content detection after top-level value

## src/serializer.cpp — Full JsonSerializer Implementation

### Content Written:
```cpp
#include "json_parser.hpp"
#include <cmath>
#include <cstdlib>
#include <cstring>
#include <sstream>
#include <iomanip>

// ============================================================================
// JsonSerializer Implementation
// ============================================================================

void JsonSerializer::write_string(const StringView& sv) {
    m_output += '"';
    for (size_t i = 0; i < sv.len; ++i) {
        char c = sv.ptr[i];
        switch (c) {
            case '"':  m_output += "\\\""; break;
            case '\\': m_output += "\\\\"; break;
            case '\b': m_output += "\\b"; break;
            case '\f': m_output += "\\f"; break;
            case '\n': m_output += "\\n"; break;
            case '\r': m_output += "\\r"; break;
            case '\t': m_output += "\\t"; break;
            default:
                if (static_cast<unsigned char>(c) < 0x20) {
                    char buf[8];
                    snprintf(buf, sizeof(buf), "\\u%04x", static_cast<unsigned char>(c));
                    m_output += buf;
                } else {
                    m_output += c;
                }
                break;
        }
    }
    m_output += '"';
}

void JsonSerializer::write_number(double n) {
    if (std::isnan(n)) {
        m_output += "null";
    } else if (std::isinf(n)) {
        m_output += "null";
    } else {
        // Check if it's an integer value
        if (n == static_cast<int64_t>(n) && std::abs(n) < static_cast<double>((static_cast<int64_t>(1) << 53))) {
            m_output += std::to_string(static_cast<int64_t>(n));
        } else {
            std::ostringstream oss;
            oss << std::setprecision(17) << n;
            m_output += oss.str();
        }
    }
}

void JsonSerializer::write_indent() {
    if (m_indent > 0) {
        for (int i = 0; i < m_depth * m_indent; ++i) {
            m_output += ' ';
        }
    }
}

void JsonSerializer::write_value(const JsonValue& value) {
    switch (value.type()) {
        case JsonValue::Type::Null:
            m_output += "null";
            break;
        case JsonValue::Type::Bool:
            m_output += value.get_bool() ? "true" : "false";
            break;
        case JsonValue::Type::Int:
            m_output += std::to_string(value.get_int());
            break;
        case JsonValue::Type::Float:
            write_number(value.get_float());
            break;
        case JsonValue::Type::String:
            write_string(value.get_string());
            break;
        case JsonValue::Type::Array: {
            auto* arr = value.get_array();
            if (arr->empty()) {
                m_output += "[]";
            } else {
                m_output += '[';
                if (m_indent > 0) {
                    m_output += '\n';
                    ++m_depth;
                    for (size_t i = 0; i < arr->size(); ++i) {
                        write_indent();
                        write_value(arr->operator[](i));
                        if (i + 1 < arr->size()) {
                            m_output += ',';
                        }
                    }
                    m_output += '\n';
                    --m_depth;
                    write_indent();
                }
                m_output += ']';
            }
            break;
        }
        case JsonValue::Type::Object: {
            auto* obj = value.get_object();
            if (obj->empty()) {
                m_output += "{}";
            } else {
                m_output += '{';
                if (m_indent > 0) {
                    m_output += '\n';
                    ++m_depth;
                    for (size_t i = 0; i < obj->size; ++i) {
                        write_indent();
                        write_string(obj->entries[i].key);
                        m_output += ':';
                        if (m_indent > 0) m_output += ' ';
                        write_value(obj->entries[i].value);
                        if (i + 1 < obj->size) {
                            m_output += ',';
                        }
                    }
                    m_output += '\n';
                    --m_depth;
                    write_indent();
                }
                m_output += '}';
            }
            break;
        }
    }
}

std::string JsonSerializer::serialize(const JsonValue& value, int indent) {
    m_output.clear();
    m_indent = indent;
    m_depth = 0;
    write_value(value);
    return m_output;
}
```

### Key Design Points:
- Compact mode (indent=-1) produces minimal JSON
- Pretty-print mode with configurable indentation depth
- Proper JSON string escaping for control characters
- Number formatting handles integers vs floats correctly
- NaN and Inf serialized as null per JSON spec
- Uses ostringstream for precise float formatting (17 digits)

