```typescript
// ============================================================================
// devbench-react-dashboard — Metric Telemetry Type System
// Software Design Phase: State Management, Component Tree, WS Protocol
// ============================================================================

// ---------------------------------------------------------------------------
// 1. Metric Categories & Units
// ---------------------------------------------------------------------------

/** Categories of telemetry metrics */
export enum MetricCategory {
  CPU = 'cpu',
  MEMORY = 'memory',
  DISK = 'disk',
  NETWORK = 'network',
  CUSTOM = 'custom',
}

/** Standard units for metric values */
export enum MetricUnit {
  PERCENT = '%',
  BYTES = 'B',
  KILOBYTES = 'KB',
  MEGABYTES = 'MB',
  GIGABYTES = 'GB',
  BITS_PER_SEC = 'bps',
  OPERATIONS_PER_SEC = 'ops',
  COUNT = '',
}

// ---------------------------------------------------------------------------
// 2. Core Metric Data Types
// ---------------------------------------------------------------------------

/** A single data point in a metric time series */
export interface MetricPoint {
  /** Unix timestamp in milliseconds */
  timestamp: number;
  /** Numeric value at this point */
  value: number;
  /** Optional dimension labels (e.g., { core: "0", zone: "us-east-1" }) */
  labels?: Record<string, string>;
}

/** Schema definition for a metric feed */
export interface MetricDefinition {
  /** Unique identifier, e.g., 'cpu.usage' or 'mem.available' */
  id: string;
  /** Human-readable display name */
  name: string;
  /** Category classification */
  category: MetricCategory;
  /** Unit of measurement */
  unit: MetricUnit;
  /** Optional description shown in tooltips */
  description?: string;
  /** Rolling history window size (default: 60 points) */
  historySize?: number;
  /** Alert thresholds */
  thresholds?: {
    warning: number;
    critical: number;
  };
}

/** Current live snapshot of a metric including its history buffer */
export interface MetricSnapshot {
  /** The schema for this metric */
  definition: MetricDefinition;
  /** Most recent value */
  currentValue: number;
  /** Previous value (null if first data point) */
  previousValue: number | null;
  /** Rolling window of historical data points */
  history: MetricPoint[];
  /** Timestamp of last update */
  lastUpdated: number;
  /** Health status derived from thresholds */
  status: MetricStatus;
}

/** Derived health status based on threshold comparison */
export enum MetricStatus {
  OK = 'ok',
  WARNING = 'warning',
  CRITICAL = 'critical',
  OFFLINE = 'offline',
}

// ---------------------------------------------------------------------------
// 3. WebSocket Subscription Protocol
// ---------------------------------------------------------------------------

/** Generic envelope for all WS messages */
export interface WSMessage<T = unknown> {
  /** Message type discriminator */
  type: string;
  /** Payload data */
  payload: T;
  /** Client-provided correlation ID for request/response matching */
  correlationId?: string;
}

// --- Client → Server Messages ---

/** Subscribe to one or more metric feeds */
export interface SubscribePayload {
  /** Array of metric IDs to subscribe to */
  metricIds: string[];
  /** Desired update interval in ms (server may adjust) */
  interval?: number;
}

/** Unsubscribe from metric feeds */
export interface UnsubscribePayload {
  /** Array of metric IDs to unsubscribe from */
  metricIds: string[];
}

/** Keepalive ping */
export interface PingPayload {}

// --- Server → Client Messages ---

/** Real-time metric data push */
export interface MetricUpdatePayload {
  /** Array of updated metric snapshots */
  metrics: MetricSnapshot[];
}

/** Connection lifecycle notification */
export interface ConnectionStatusPayload {
  status: 'connected' | 'connecting' | 'disconnected' | 'reconnecting';
  reason?: string;
}

/** Error notification from server */
export interface ErrorPayload {
  code: string;
  message: string;
  details?: unknown;
}

/** Keepalive pong response */
export interface PongPayload {
  serverTimestamp: number;
}

// ---------------------------------------------------------------------------
// 4. Application State (useReducer shape)
// ---------------------------------------------------------------------------

/** Global dashboard application state */
export interface DashboardState {
  /** Map of metric ID → current snapshot */
  metrics: Record<string, MetricSnapshot>;
  /** Set of currently subscribed metric IDs */
  subscriptions: Set<string>;
  /** Current WebSocket connection status */
  connectionStatus: 'connected' | 'connecting' | 'disconnected' | 'reconnecting';
  /** Last error encountered (null when healthy) */
  error: ErrorPayload | null;
  /** UI-specific state */
  ui: {
    /** Currently selected metric IDs for detailed view */
    selectedMetricIds: string[];
    /** Manual refresh interval in ms (0 = auto-only) */
    refreshInterval: number;
    /** Color theme */
    theme: 'light' | 'dark';
  };
}

/** Reducer action union type */
export type DashboardAction =
  | { type: 'METRIC_UPDATE'; payload: MetricSnapshot[] }
  | { type: 'SUBSCRIBE_METRICS'; payload: string[] }
  | { type: 'UNSUBSCRIBE_METRICS'; payload: string[] }
  | { type: 'SET_CONNECTION_STATUS'; payload: DashboardState['connectionStatus'] }
  | { type: 'SET_ERROR'; payload: ErrorPayload | null }
  | { type: 'SELECT_METRIC'; payload: string }
  | { type: 'DESELECT_METRIC'; payload: string }
  | { type: 'SET_THEME'; payload: 'light' | 'dark' }
  | { type: 'RESET' };

// ---------------------------------------------------------------------------
// 5. React Context & Hook Contracts
// ---------------------------------------------------------------------------

/** Shape exposed by DashboardContext */
export interface DashboardContextType extends DashboardState {
  dispatch: React.Dispatch<DashboardAction>;
  subscribe: (metricIds: string[]) => void;
  unsubscribe: (metricIds: string[]) => void;
  connect: () => void;
  disconnect: () => void;
}

/** Return type of useMetrics custom hook */
export interface UseMetricsReturn {
  metrics: Record<string, MetricSnapshot>;
  getMetric: (id: string) => MetricSnapshot | undefined;
  getMetricsByCategory: (category: MetricCategory) => MetricSnapshot[];
}

/** Return type of useWebSocket custom hook */
export interface UseWebSocketReturn {
  isConnected: boolean;
  connect: () => void;
  disconnect: () => void;
  send: (message: WSMessage) => void;
}

// ---------------------------------------------------------------------------
// 6. Default Constants & Configuration
// ---------------------------------------------------------------------------

/** Default WebSocket endpoint */
export const DEFAULT_WS_URL = 'ws://localhost:8080/ws/metrics';

/** Default rolling history window size */
export const DEFAULT_HISTORY_SIZE = 60;

/** Heartbeat interval in ms */
export const HEARTBEAT_INTERVAL_MS = 15_000;

/** Reconnection base delay in ms */
export const RECONNECT_BASE_DELAY_MS = 1_000;

/** Maximum reconnection delay in ms */
export const RECONNECT_MAX_DELAY_MS = 30_000;

/** Number of missed pings before declaring disconnected */
export const MAX_MISSED_PINGS = 3;

/** Initial dashboard state factory */
export function createInitialState(): DashboardState {
  return {
    metrics: {},
    subscriptions: new Set(),
    connectionStatus: 'disconnected',
    error: null,
    ui: {
      selectedMetricIds: [],
      refreshInterval: 0,
      theme: 'dark',
    },
  };
}
```

---

## Design Rationale

| Decision | Rationale |
|----------|-----------|
| `MetricPoint` with optional `labels` | Supports multi-dimensional metrics (cores, zones, containers) without bloating simple cases |
| `MetricSnapshot` wraps `MetricDefinition` | Each snapshot carries its own schema, enabling dynamic metric registration |
| `Set<string>` for subscriptions | O(1) membership checks; avoids array duplication bugs |
| `correlationId` on WS messages | Enables request/response matching for subscribe/unsubscribe confirmations |
| Exponential backoff constants | Prevents thundering herd during outages; configurable via constants |
| `createInitialState()` factory | Ensures consistent initial state across SSR/hydration boundaries |

