# events.proto
# Protobuf schema for gRPC event streaming microservice
# 
# Usage: protoc --go_out=. --go-grpc_out=. --proto_path=. proto/events.proto

syntax = "proto3";

package events;

option go_package = "devbench-go-microservice/proto/events";

// ============================================================================
// ENUMERATIONS
// ============================================================================

// Event type classification
enum EventType {
  EVENT_TYPE_UNSPECIFIED = 0;
  EVENT_TYPE_CREATE      = 1;
  EVENT_TYPE_UPDATE      = 2;
  EVENT_TYPE_DELETE      = 3;
  EVENT_TYPE_CUSTOM      = 4;
}

// Stream status codes
enum StreamStatus {
  STREAM_STATUS_OK           = 0;
  STREAM_STATUS_DISCONNECTED = 1;
  STREAM_STATUS_ERROR        = 2;
  STREAM_STATUS_CLOSED       = 3;
}

// ============================================================================
// MESSAGE DEFINITIONS
// ============================================================================

// Event represents a domain event in the system
message Event {
  // Unique identifier (UUID v4)
  string id = 1;

  // Type of event
  EventType type = 2;

  // Binary payload containing event data
  bytes payload = 3;

  // ISO 8601 timestamp when event was created
  string timestamp = 4;

  // Source service/component that generated the event
  string source = 5;

  // Arbitrary key-value metadata
  map<string, string> metadata = 6;

  // Version number for optimistic concurrency
  int64 version = 7;
}

// EventEnvelope wraps an Event with stream metadata
message EventEnvelope {
  Event event = 1;
  StreamStatus status = 2;
  // Sequence number for ordering guarantees
  int64 sequence = 3;
}

// ============================================================================
// REQUEST / RESPONSE MESSAGES
// ============================================================================

// PublishEventRequest: publish a single event
message PublishEventRequest {
  Event event = 1;
  // If true, wait for acknowledgment before returning
  bool await_ack = 2;
}

// PublishEventResponse: result of publishing
message PublishEventResponse {
  bool success = 1;
  string event_id = 2;
  string error_message = 3;
  // Server-assigned sequence number
  int64 sequence = 4;
}

// GetEventRequest: retrieve event by ID
message GetEventRequest {
  string id = 1;
  // Whether to force cache refresh
  bool bypass_cache = 2;
}

// GetEventResponse: retrieved event
message GetEventResponse {
  Event event = 1;
  bool from_cache = 2;
}

// QueryEventsFilter: filter criteria for querying events
message QueryEventsFilter {
  EventType event_type = 1;
  string source = 2;
  // Filter events after this timestamp
  string start_time = 3;
  // Filter events before this timestamp
  string end_time = 4;
  // Maximum number of results
  int32 limit = 5;
  // Offset for pagination
  int32 offset = 6;
  // Metadata key-value filter (exact match)
  map<string, string> metadata_filter = 7;
}

// QueryEventsRequest: query events with filters
message QueryEventsRequest {
  QueryEventsFilter filter = 1;
}

// QueryEventsResponse: paginated event results
message QueryEventsResponse {
  repeated Event events = 1;
  // Total count matching filter (ignoring limit/offset)
  int64 total_count = 2;
  // Token for next page (empty if last page)
  string next_page_token = 3;
}

// SubscribeEventsRequest: subscribe to event stream
message SubscribeEventsRequest {
  // Optional filter to narrow subscribed events
  QueryEventsFilter filter = 1;
  // Replay events from this sequence number
  int64 replay_from_sequence = 2;
}

// SubscribeEventsResponse: streamed event envelope
message SubscribeEventsResponse {
  EventEnvelope envelope = 1;
}

// GetMetricsRequest: request metrics snapshot
message GetMetricsRequest {}

// MetricEntry: single metric point
message MetricEntry {
  string name = 1;
  string help = 2;
  string type = 3;  // counter, gauge, histogram, summary
  double value = 4;
  map<string, string> labels = 5;
}

// GetMetricsResponse: Prometheus-compatible metrics
message GetMetricsResponse {
  repeated MetricEntry metrics = 1;
  // Timestamp of metrics collection
  string collected_at = 2;
}

// HealthCheckRequest
message HealthCheckRequest {}

// HealthCheckResponse
message HealthCheckResponse {
  string status = 1;          // "SERVING", "NOT_SERVING", "UNKNOWN"
  string version = 2;
  int64 uptime_seconds = 3;
  int64 active_subscribers = 4;
  int64 events_published_total = 5;
}

// ============================================================================
// SERVICE DEFINITION
// ============================================================================

// EventService provides gRPC endpoints for event streaming operations
service EventService {

  // PublishEvent publishes a single event to the stream.
  // Returns success status and assigned sequence number.
  rpc PublishEvent(PublishEventRequest) returns (PublishEventResponse);

  // SubscribeEvents is a server-streaming RPC that delivers events
  // in real-time to connected clients. Supports filtering and replay.
  rpc SubscribeEvents(SubscribeEventsRequest) 
      returns (stream SubscribeEventsResponse);

  // GetEvent retrieves a specific event by ID.
  // Checks Redis cache first, falls back to event store.
  rpc GetEvent(GetEventRequest) returns (GetEventResponse);

  // QueryEvents is a client-streaming RPC that allows clients to send
  // multiple query requests and receive paginated results.
  rpc QueryEvents(stream QueryEventsRequest) 
      returns (QueryEventsResponse);

  // GetMetrics returns current system metrics in Prometheus format.
  rpc GetMetrics(GetMetricsRequest) returns (GetMetricsResponse);

  // HealthCheck returns service health and operational status.
  rpc HealthCheck(HealthCheckRequest) returns (HealthCheckResponse);
}

// Package handlers implements gRPC server handlers for the event streaming microservice.
// It provides unary and streaming RPC implementations for event publishing, subscription, retrieval, querying, and metrics.
package handlers

import (
	"context"
	"fmt"
	"log"
	"sync"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/promauto"
	pb "devbench-go-microservice/proto" // Generated protobuf package
	redisclient "devbench-go-microservice/internal/storage"
	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/metadata"
	"google.golang.org/grpc/status"
)

// ---------------------------------------------------------------------------
// Protobuf-generated types (assumed available via proto/events.proto)
// ---------------------------------------------------------------------------

// EventType maps to the enum defined in proto/events.proto
type EventType = pb.EventType

const (
	EventType_CREATE  EventType = pb.EventType_CREATE
	EventType_UPDATE  EventType = pb.EventType_UPDATE
	EventType_DELETE  EventType = pb.EventType_DELETE
	EventType_CUSTOM  EventType = pb.EventType_CUSTOM
)

// Event maps to the message defined in proto/events.proto
type Event struct {
	ID        string            `json:"id"`
	Type      EventType         `json:"type"`
	Payload   []byte            `json:"payload"`
	Timestamp time.Time         `json:"timestamp"`
	Source    string            `json:"source"`
	Metadata  map[string]string `json:"metadata"`
}

// ---------------------------------------------------------------------------
// Prometheus Metrics
// ---------------------------------------------------------------------------

var (
	grpcServerHandledTotal = promauto.NewCounterVec(
		prometheus.CounterOpts{
			Name: "grpc_server_handled_total",
			Help: "Total number of gRPC requests handled by the server.",
		},
		[]string{"method", "status"},
	)

	grpcServerHandlingSeconds = promauto.NewHistogramVec(
		prometheus.HistogramOpts{
			Name:    "grpc_server_handling_seconds",
			Help:    "Duration of gRPC request handling in seconds.",
			Buckets: prometheus.DefBuckets,
		},
		[]string{"method"},
	)

	redisCacheHitsTotal = promauto.NewCounter(
		prometheus.CounterOpts{
			Name: "redis_cache_hits_total",
			Help: "Total number of Redis cache hits.",
		},
	)

	redisCacheMissesTotal = promauto.NewCounter(
		prometheus.CounterOpts{
			Name: "redis_cache_misses_total",
			Help: "Total number of Redis cache misses.",
		},
	)

	eventsPublishedTotal = promauto.NewCounter(
		prometheus.CounterOpts{
			Name: "events_published_total",
			Help: "Total number of events published to the stream.",
		},
	)

	activeSubscribersCount = promauto.NewGauge(
		prometheus.GaugeOpts{
			Name: "active_subscribers_count",
			Help: "Current number of active event subscribers.",
		},
	)
)

// ---------------------------------------------------------------------------
// Server Implementation
// ---------------------------------------------------------------------------

// Server implements the gRPC EventService server.
type Server struct {
	pb.UnimplementedEventServiceServer
	redisClient *redisclient.RedisClient
	mu          sync.RWMutex
	subscribers map[chan *pb.Event]struct{}
}

// NewServer creates a new gRPC server instance.
func NewServer(redisClient *redisclient.RedisClient) *Server {
	return &Server{
		redisClient: redisClient,
		subscribers: make(map[chan *pb.Event]struct{}),
	}
}

// ---------------------------------------------------------------------------
// Helper: context extraction
// ---------------------------------------------------------------------------

func extractRequestID(ctx context.Context) string {
	md, ok := metadata.FromIncomingContext(ctx)
	if !ok {
		return ""
	}
	values := md.Get("x-request-id")
	if len(values) > 0 {
		return values[0]
	}
	return ""
}

// ---------------------------------------------------------------------------
// PublishEvent — Unary RPC
// Publishes a single event to the Redis stream and broadcasts to subscribers.
// ---------------------------------------------------------------------------

func (s *Server) PublishEvent(ctx context.Context, req *pb.PublishEventRequest) (*pb.PublishEventResponse, error) {
	start := time.Now()
	requestID := extractRequestID(ctx)
	method := "PublishEvent"

	defer func() {
		grpcServerHandlingSeconds.WithLabelValues(method).Observe(time.Since(start).Seconds())
	}()

	if req.GetEvent() == nil {
		grpcServerHandledTotal.WithLabelValues(method, codes.InvalidArgument.String()).Inc()
		return nil, status.Error(codes.InvalidArgument, "event is required")
	}

	event := req.GetEvent()

	// Validate event type
	switch event.Type {
	case pb.EventType_CREATE, pb.EventType_UPDATE, pb.EventType_DELETE, pb.EventType_CUSTOM:
		// Valid type
	default:
		grpcServerHandledTotal.WithLabelValues(method, codes.InvalidArgument.String()).Inc()
		return nil, status.Error(codes.InvalidArgument, fmt.Sprintf("invalid event type: %v", event.Type))
	}

	// Set default timestamp if not provided
	if event.Timestamp == 0 {
		event.Timestamp = time.Now().UnixNano()
	}

	// Store event in Redis
	err := s.redisClient.StoreEvent(ctx, event)
	if err != nil {
		log.Printf("[PublishEvent] failed to store event %s: %v", event.Id, err)
		grpcServerHandledTotal.WithLabelValues(method, codes.Internal.String()).Inc()
		return nil, status.Error(codes.Internal, "failed to store event")
	}

	// Invalidate related cache entries on UPDATE/DELETE
	if event.Type == pb.EventType_UPDATE || event.Type == pb.EventType_DELETE {
		s.redisClient.InvalidateCache(ctx, event.Id)
	}

	// Broadcast to all active subscribers
	s.broadcastToSubscribers(event)

	// Update metrics
	eventsPublishedTotal.Inc()
	grpcServerHandledTotal.WithLabelValues(method, codes.OK.String()).Inc()

	return &pb.PublishEventResponse{
		Success: true,
		EventId: event.Id,
		Message: "event published successfully",
	}, nil
}

// ---------------------------------------------------------------------------
// SubscribeEvents — Server-streaming RPC
// Streams real-time events to connected clients via Redis Pub/Sub.
// ---------------------------------------------------------------------------

func (s *Server) SubscribeEvents(req *pb.SubscribeEventsRequest, stream pb.EventService_SubscribeEventsServer) error {
	method := "SubscribeEvents"
	start := time.Now()

	// Create a channel for this subscriber
	ch := make(chan *pb.Event, 100)

	// Register subscriber
	s.mu.Lock()
	s.subscribers[ch] = struct{}{}
	s.mu.Unlock()

	activeSubscribersCount.Inc()
	defer func() {
		s.mu.Lock()
		delete(s.subscribers, ch)
		s.mu.Unlock()
		activeSubscribersCount.Dec()
		grpcServerHandledTotal.WithLabelValues(method, codes.OK.String()).Inc()
	}()

	// If filter is specified, only send matching events
	filterType := req.GetType()

	// Send historical events if requested
	if req.GetHistorySize() > 0 {
		historical, err := s.redisClient.GetHistoricalEvents(stream.Context(), int(req.GetHistorySize()))
		if err != nil {
			log.Printf("[SubscribeEvents] failed to fetch historical events: %v", err)
		} else {
			for _, evt := range historical {
				if filterType != pb.EventType_CUSTOM && evt.Type != filterType {
					continue
				}
				if err := stream.Send(evt); err != nil {
					return status.Errorf(codes.Canceled, "stream send failed: %v", err)
				}
			}
		}
	}

	// Stream live events
	for {
		select {
		case <-stream.Context().Done():
			return stream.Context().Err()
		case evt, ok := <-ch:
			if !ok {
				return nil
			}
			if filterType != pb.EventType_CUSTOM && evt.Type != filterType {
				continue
			}
			if err := stream.Send(evt); err != nil {
				return status.Errorf(codes.Canceled, "stream send failed: %v", err)
			}
		}
	}
}

// broadcastToSubscribers sends an event to all registered subscribers.
func (s *Server) broadcastToSubscribers(event *pb.Event) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	for ch := range s.subscribers {
		select {
		case ch <- event:
		default:
			// Subscriber channel is full, skip to avoid blocking
		}
	}
}

// ---------------------------------------------------------------------------
// GetEvent — Unary RPC
// Retrieves a specific event by ID with Redis cache lookup.
// ---------------------------------------------------------------------------

func (s *Server) GetEvent(ctx context.Context, req *pb.GetEventRequest) (*pb.GetEventResponse, error) {
	method := "GetEvent"
	start := time.Now()

	if req.GetId() == "" {
		grpcServerHandledTotal.WithLabelValues(method, codes.InvalidArgument.String()).Inc()
		return nil, status.Error(codes.InvalidArgument, "event ID is required")
	}

	eventID := req.GetId()

	// Try cache first
	cached, err := s.redisClient.GetCachedEvent(ctx, eventID)
	if err == nil && cached != nil {
		redisCacheHitsTotal.Inc()
		grpcServerHandledTotal.WithLabelValues(method, codes.OK.String()).Inc()
		grpcServerHandlingSeconds.WithLabelValues(method).Observe(time.Since(start).Seconds())
		return &pb.GetEventResponse{
			Event: cached,
			CacheHit: true,
		}, nil
	}

	redisCacheMissesTotal.Inc()

	// Cache miss — fetch from primary store (Redis stream / PostgreSQL)
	event, err := s.redisClient.FetchEvent(ctx, eventID)
	if err != nil {
		log.Printf("[GetEvent] failed to fetch event %s: %v", eventID, err)
		grpcServerHandledTotal.WithLabelValues(method, codes.NotFound.String()).Inc()
		return nil, status.Error(codes.NotFound, fmt.Sprintf("event %s not found", eventID))
	}

	// Populate cache for future lookups
	ttl := s.redisClient.GetTTLForType(event.Type)
	s.redisClient.SetCachedEvent(ctx, eventID, event, ttl)

	grpcServerHandledTotal.WithLabelValues(method, codes.OK.String()).Inc()
	grpcServerHandlingSeconds.WithLabelValues(method).Observe(time.Since(start).Seconds())

	return &pb.GetEventResponse{
		Event:    event,
		CacheHit: false,
	}, nil
}

// ---------------------------------------------------------------------------
// QueryEvents — Client-streaming RPC
// Accepts a stream of query filters and returns matching events.
// ---------------------------------------------------------------------------

func (s *Server) QueryEvents(stream pb.EventService_QueryEventsServer) error {
	method := "QueryEvents"
	start := time.Now()

	var eventType pb.EventType = pb.EventType_CUSTOM
	var sourceFilter string
	var limit int32 = 100

	// Read all incoming filter messages
	for {
		req, err := stream.Recv()
		if err != nil {
			break
		}
		if req.GetFilter() != nil {
			f := req.GetFilter()
			if f.Type != pb.EventType_CUSTOM {
				eventType = f.Type
			}
			if f.Source != "" {
				sourceFilter = f.Source
			}
			if f.Limit > 0 {
				limit = f.Limit
			}
		}
	}

	// Execute query against Redis
	events, err := s.redisClient.QueryEvents(stream.Context(), eventType, sourceFilter, int(limit))
	if err != nil {
		log.Printf("[QueryEvents] query failed: %v", err)
		grpcServerHandledTotal.WithLabelValues(method, codes.Internal.String()).Inc()
		return status.Error(codes.Internal, "query failed")
	}

	// Stream results back
	for _, evt := range events {
		if err := stream.Send(&pb.QueryEventsResponse{Event: evt}); err != nil {
			return status.Errorf(codes.Canceled, "stream send failed: %v", err)
		}
	}

	grpcServerHandledTotal.WithLabelValues(method, codes.OK.String()).Inc()
	grpcServerHandlingSeconds.WithLabelValues(method).Observe(time.Since(start).Seconds())

	return nil
}

// ---------------------------------------------------------------------------
// GetMetrics — Unary RPC
// Returns Prometheus-compatible metrics as a serialized response.
// ---------------------------------------------------------------------------

func (s *Server) GetMetrics(ctx context.Context, req *pb.GetMetricsRequest) (*pb.GetMetricsResponse, error) {
	method := "GetMetrics"
	start := time.Now()

	// Gather custom metrics
	metrics := &pb.MetricsData{
		GrpcHandledTotal:     make(map[string]int64),
		EventsPublishedTotal: eventsPublishedTotal.Count(),
		ActiveSubscribers:    int64(activeSubscribersCount.Value()),
		RedisCacheHits:       redisCacheHitsTotal.Count(),
		RedisCacheMisses:     redisCacheMissesTotal.Count(),
	}

	// Extract grpc_server_handled_total labels
	grpcServerHandledTotal.Range(func(m prometheus.Metric, mdata prometheus.MetricMetadata) bool {
		labelMap := make(map[string]string)
		for _, lp := range mdata.Labels {
			labelMap[lp.Name] = lp.Value
		}
		key := labelMap["method"] + "/" + labelMap["status"]
		metrics.GrpcHandledTotal[key]++
		return true
	})

	grpcServerHandledTotal.WithLabelValues(method, codes.OK.String()).Inc()
	grpcServerHandlingSeconds.WithLabelValues(method).Observe(time.Since(start).Seconds())

	return &pb.GetMetricsResponse{
		Metrics: metrics,
	}, nil
}

// ---------------------------------------------------------------------------
// RegisterService — gRPC service registration helper
// ---------------------------------------------------------------------------

// RegisterService registers the EventService with a gRPC server.
func RegisterService(server *grpc.Server, redisClient *redisclient.RedisClient) {
	pb.RegisterEventServiceServer(server, NewServer(redisClient))
}

// Package handlers implements gRPC event streaming service handlers
// for the devbench-go-microservice.
package handlers

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"

	pb "devbench-go-microservice/proto"
	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/credentials/insecure"
	"google.golang.org/grpc/test/bufconn"
	"google.golang.org/protobuf/types/known/timestamppb"
)

// ---------------------------------------------------------------------------
// Event Types (matching proto enum)
// ---------------------------------------------------------------------------

// EventType represents the type of an event.
type EventType string

const (
	EventTypeCreate EventType = "CREATE"
	EventTypeUpdate EventType = "UPDATE"
	EventTypeDelete EventType = "DELETE"
	EventTypeCustom EventType = "CUSTOM"
)

// ---------------------------------------------------------------------------
// Interfaces for dependency injection (testability)
// ---------------------------------------------------------------------------

// RedisClient defines the interface for Redis operations needed by the handler.
type RedisClient interface {
	Get(ctx context.Context, key string) (*string, error)
	Set(ctx context.Context, key, value string, ttl time.Duration) error
	Del(ctx context.Context, keys ...string) error
	Publish(ctx context.Context, channel string, message string) error
	Subscribe(ctx context.Context, channels ...string) (*PubSubClient, error)
	Close() error
}

// PubSubClient represents a Redis pub/sub connection.
type PubSubClient interface {
	Receive(context.Context) (string, error)
	Close() error
}

// EventStore defines the interface for PostgreSQL event storage.
type EventStore interface {
	CreateEvent(ctx context.Context, event *pb.Event) error
	GetEvent(ctx context.Context, id string) (*pb.Event, error)
	QueryEvents(ctx context.Context, eventType, source string, limit int) ([]*pb.Event, error)
	DeleteEvent(ctx context.Context, id string) error
}

// MetricsProvider defines the interface for Prometheus metrics.
type MetricsProvider interface {
	RecordRequest(duration time.Duration, method string, status codes.Code)
	IncrementCacheHit()
	IncrementCacheMiss()
	IncrementEventsPublished()
	UpdateSubscriberCount(count int)
}

// ---------------------------------------------------------------------------
// EventHandler – the gRPC service implementation
// ---------------------------------------------------------------------------

// EventHandler handles gRPC requests for event streaming operations.
type EventHandler struct {
	pb.UnimplementedEventServiceServer

	redis    RedisClient
	store    EventStore
	metrics  MetricsProvider
	subMu    sync.RWMutex
	subs     map[string]*subscriber
	bufConn  *bufconn.Listener
	server   *grpc.Server
}

// subscriber holds state for a single server-streaming subscription.
type subscriber struct {
	stream pb.EventService_SubscribeEventsServer
	done   chan struct{}
}

// NewEventHandler creates a new EventHandler with the given dependencies.
func NewEventHandler(redis RedisClient, store EventStore, metrics MetricsProvider) *EventHandler {
	return &EventHandler{
		redis:   redis,
		store:   store,
		metrics: metrics,
		subs:    make(map[string]*subscriber),
	}
}

// ---------------------------------------------------------------------------
// PublishEvent – unary RPC
// ---------------------------------------------------------------------------

// PublishEvent publishes a single event to the stream.
func (h *EventHandler) PublishEvent(ctx context.Context, req *pb.PublishEventRequest) (*pb.PublishEventResponse, error) {
	start := time.Now()
	defer func() {
		h.metrics.RecordRequest(time.Since(start), "/EventService/PublishEvent", codes.OK)
	}()

	if req.Event == nil {
		return nil, errors.New("event is required")
	}
	if req.Event.Id == "" {
		return nil, fmt.Errorf("event id is required")
	}

	// Validate event type
	switch req.Event.Type {
	case pb.EventType_CREATE, pb.EventType_UPDATE, pb.EventType_DELETE, pb.EventType_CUSTOM:
		// valid
	default:
		return nil, fmt.Errorf("invalid event type: %v", req.Event.Type)
	}

	// Set timestamp if not provided
	if req.Event.Timestamp == nil {
		req.Event.Timestamp = timestamppb.Now()
	}

	// Store in database
	if err := h.store.CreateEvent(ctx, req.Event); err != nil {
		h.metrics.RecordRequest(time.Since(start), "/EventService/PublishEvent", codes.Internal)
		return nil, fmt.Errorf("failed to store event: %w", err)
	}

	// Invalidate cache for this event
	cacheKey := fmt.Sprintf("event:%s", req.Event.Id)
	h.redis.Del(ctx, cacheKey)

	// Publish to Redis pub/sub for subscribers
	if err := h.redis.Publish(ctx, "events", fmt.Sprintf("%s", req.Event.Id)); err != nil {
		// Non-fatal – log but don't fail the request
		fmt.Printf("warning: failed to publish to pub/sub: %v\n", err)
	}

	// Update subscriber count
	h.subMu.RLock()
	count := len(h.subs)
	h.subMu.RUnlock()
	h.metrics.UpdateSubscriberCount(count)

	h.metrics.IncrementEventsPublished()

	return &pb.PublishEventResponse{
		Success: true,
		EventId: req.Event.Id,
	}, nil
}

// ---------------------------------------------------------------------------
// SubscribeEvents – server-streaming RPC
// ---------------------------------------------------------------------------

// SubscribeEvents subscribes to the real-time event stream.
func (h *EventHandler) SubscribeEvents(req *pb.SubscribeEventsRequest, stream pb.EventService_SubscribeEventsServer) error {
	start := time.Now()
	defer h.metrics.RecordRequest(time.Since(start), "/EventService/SubscribeEvents", codes.OK)

	subID := fmt.Sprintf("sub-%d", time.Now().UnixNano())

	h.subMu.Lock()
	h.subs[subID] = &subscriber{
		stream: stream,
		done:   make(chan struct{}),
	}
	h.subMu.Unlock()

	// Update subscriber count metric
	h.subMu.RLock()
	count := len(h.subs)
	h.subMu.RUnlock()
	h.metrics.UpdateSubscriberCount(count)

	// Listen for events from Redis pub/sub
	ch, err := h.redis.Subscribe(stream.Context(), "events")
	if err != nil {
		return fmt.Errorf("failed to subscribe to events: %w", err)
	}
	defer ch.Close()

	for {
		select {
		case <-stream.Context().Done():
			h.cleanupSubscriber(subID)
			return stream.Context().Err()
		case <-h.subs[subID].done:
			return nil
		case msg, ok := <-ch.(interface{ Receive(context.Context) (string, error) }):
			if !ok {
				h.cleanupSubscriber(subID)
				return errors.New("pub/sub connection closed")
			}
			eventID := msg
			// Fetch event from cache or store
			event, err := h.getEvent(stream.Context(), eventID)
			if err != nil {
				continue // skip unavailable events
			}
			if err := stream.Send(&pb.SubscribeEventsResponse{Event: event}); err != nil {
				h.cleanupSubscriber(subID)
				return err
			}
		}
	}
}

// cleanupSubscriber removes a subscriber from the active set.
func (h *EventHandler) cleanupSubscriber(subID string) {
	h.subMu.Lock()
	defer h.subMu.Unlock()
	if sub, ok := h.subs[subID]; ok {
		close(sub.done)
		delete(h.subs, subID)
	}
	count := len(h.subs)
	h.metrics.UpdateSubscriberCount(count)
}

// ---------------------------------------------------------------------------
// GetEvent – unary RPC with cache lookup
// ---------------------------------------------------------------------------

// GetEvent retrieves a specific event by ID, checking the cache first.
func (h *EventHandler) GetEvent(ctx context.Context, req *pb.GetEventRequest) (*pb.GetEventResponse, error) {
	start := time.Now()
	defer func() {
		h.metrics.RecordRequest(time.Since(start), "/EventService/GetEvent", codes.OK)
	}()

	if req.Id == "" {
		return nil, fmt.Errorf("event id is required")
	}

	cacheKey := fmt.Sprintf("event:%s", req.Id)

	// Try cache first
	val, err := h.redis.Get(ctx, cacheKey)
	if err == nil && val != nil {
		h.metrics.IncrementCacheHit()
		// Deserialize cached event (simplified – in production use JSON/msgpack)
		var event pb.Event
		_ = event.UnmarshalVT([]byte(*val)) // pseudo-code; actual deserialization depends on format
		return &pb.GetEventResponse{
			Event:      &event,
			CacheHit:   true,
			StatusCode: 200,
		}, nil
	}
	h.metrics.IncrementCacheMiss()

	// Fall back to database
	event, err := h.store.GetEvent(ctx, req.Id)
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			return &pb.GetEventResponse{
				StatusCode: 404,
				Error:      "event not found",
			}, nil
		}
		return nil, fmt.Errorf("failed to get event: %w", err)
	}

	// Cache the result (5-minute TTL)
	ttl := 5 * time.Minute
	eventData, _ := event.MarshalVT() // pseudo-code
	h.redis.Set(ctx, cacheKey, string(eventData), ttl)

	return &pb.GetEventResponse{
		Event:      event,
		CacheHit:   false,
		StatusCode: 200,
	}, nil
}

// ---------------------------------------------------------------------------
// QueryEvents – client-streaming RPC
// ---------------------------------------------------------------------------

// QueryEvents queries events based on filters sent via client stream.
func (h *EventHandler) QueryEvents(stream pb.EventService_QueryEventsServer) error {
	start := time.Now()
	defer h.metrics.RecordRequest(time.Since(start), "/EventService/QueryEvents", codes.OK)

	var eventType, source string
	limit := 100

	// Read filter requests from client
	for {
		req, err := stream.Recv()
		if err != nil {
			return err
		}
		if req.Filter != nil {
			if req.Filter.EventType != "" {
				eventType = string(req.Filter.EventType)
			}
			if req.Filter.Source != "" {
				source = req.Filter.Source
			}
			if req.Filter.Limit > 0 && req.Filter.Limit < limit {
				limit = int(req.Filter.Limit)
			}
		}
	}
}

// ---------------------------------------------------------------------------
// GetMetrics – unary RPC
// ---------------------------------------------------------------------------

// GetMetrics returns Prometheus-compatible metrics snapshot.
func (h *EventHandler) GetMetrics(ctx context.Context, req *pb.GetMetricsRequest) (*pb.GetMetricsResponse, error) {
	start := time.Time{}
	_ = start

	h.subMu.RLock()
	subCount := len(h.subs)
	h.subMu.RUnlock()

	return &pb.GetMetricsResponse{
		ActiveSubscribers: int32(subCount),
		Timestamp:         timestamppb.Now(),
	}, nil
}

// ---------------------------------------------------------------------------
// Helper methods
// ---------------------------------------------------------------------------

// getEvent fetches an event from cache or database.
func (h *EventHandler) getEvent(ctx context.Context, id string) (*pb.Event, error) {
	cacheKey := fmt.Sprintf("event:%s", id)

	val, err := h.redis.Get(ctx, cacheKey)
	if err == nil && val != nil {
		h.metrics.IncrementCacheHit()
		// deserialize...
		return nil, nil
	}
	h.metrics.IncrementCacheMiss()

	return h.store.GetEvent(ctx, id)
}

// ---------------------------------------------------------------------------
// bufconn setup helpers for testing
// ---------------------------------------------------------------------------

const bufSize = 1024 * 1024

// newBufconnListener creates a bufconn listener for in-memory gRPC testing.
func newBufconnListener() *bufconn.Listener {
	return bufconn.Listen(bufSize)
}

// registerTestService registers the event service on a gRPC server using bufconn.
func registerTestService(srv *grpc.Server, handler *EventHandler) {
	pb.RegisterEventServiceServer(srv, handler)
}

// dialBufconn creates a gRPC client connection over bufconn.
func dialBufconn(ctx context.Context, lis *bufconn.Listener) (*grpc.ClientConn, error) {
	return grpc.DialContext(ctx, "bufnet",
		grpc.WithContextDialer(func(context.Context, string) (net.Conn, error) {
			return lis.Dial()
		}),
		grpc.WithTransportCredentials(insecure.NewCredentials()),
	)
}

